        }        

        //把材质参数序列化下来
        public void StoreMaterial(Material material)
        {
            if (serializedData == null)
            {
                serializedData = new SerializedMaterialData();   
            }

            serializedData.Clear();
            serializedData.shaderName = material.shader.name;

            // serializedData.enableInstancing = material.enableInstancing;
            // serializedData.renderQueue = material.renderQueue;
            // serializedData.doubleSidedGI = material.doubleSidedGI;
            // serializedData.globalIlluminationFlags = material.globalIlluminationFlags;
            // serializedData.vertexSkinningFlag = material.VertexSkinningFlag;
            foreach (var keyword in material.shaderKeywords)
            {
                serializedData.shaderKeywords.Add(keyword, material.IsKeywordEnabled(keyword));
            }

            int count = material.shader.GetPropertyCount();
            for (int i = 0; i < count; i++)
            {
                var propertyName = material.shader.GetPropertyName(i);
                var propertyType = material.shader.GetPropertyType(i);
                switch (propertyType) {
                    case ShaderPropertyType.Int:
                        serializedData.intParamValues.Add(propertyName, material.GetInt(propertyName));
                        break;
                    case ShaderPropertyType.Float:
                        serializedData.floatParamValues.Add(propertyName, material.GetFloat(propertyName));
                        break;
                    case ShaderPropertyType.Range:
                        var value = material.GetFloat(propertyName);
                        var range = material.shader.GetPropertyRangeLimits(i);
                        var serializedRange = new SerializedRange()
                        {
                            value = value,
                            range = range
                        };
                        serializedData.rangeParamValues.Add(propertyName, serializedRange);
                        break;
                    case ShaderPropertyType.Vector:
                        serializedData.vectorParamValues.Add(propertyName, material.GetVector(propertyName));
                        break;
                    case ShaderPropertyType.Color:
                        serializedData.colorParamValues.Add(propertyName, material.GetColor(propertyName));
                        break;
                    case ShaderPropertyType.Texture:
                        var texture = material.GetTexture(propertyName);
                        var path = AssetDatabase.GetAssetPath(texture);
                        var guid = AssetDatabase.AssetPathToGUID(path);
                        var tilling = material.GetTextureScale(propertyName);
                        var offset = material.GetTextureOffset(propertyName);
                        serializedData.textureParamValues.Add(propertyName, new SerializedTexture()
                        {
                            guid = guid,
                            tilling = tilling,
                            offset = offset,
                        });
                        break;
                }
            }
            json = JsonUtility.ToJson(serializedData);
        }

        public bool Equals(Material material)
        {
            if (!material) return false;
            if (serializedData == null) return false;
            //是否shader一致
            if (material.shader.name != serializedData.shaderName) return false;
            //一些其他参数是否一致
            // if (material.enableInstancing != serializedData.enableInstancing) return false;
            // if (material.renderQueue != serializedData.renderQueue) return false;
            // if (material.doubleSidedGI != serializedData.doubleSidedGI) return false;
            // if (material.globalIlluminationFlags != serializedData.globalIlluminationFlags) return false;
            // if (material.VertexSkinningFlag != serializedData.vertexSkinningFlag) return false;
            //keyword是否一致
            foreach (var keyword in material.shaderKeywords)
            {
                if (!serializedData.shaderKeywords.ContainsKey(keyword)) return false;
                if (serializedData.shaderKeywords[keyword] != material.IsKeywordEnabled(keyword)) return false;
            }
            int count = material.shader.GetPropertyCount();
            //遍历材质参数
            for (int i = 0; i < count; i++)
            {
                string propertyName = material.shader.GetPropertyName(i);
                var propertyType = material.shader.GetPropertyType(i);
                // check param value
                switch (propertyType)
                {
                    case ShaderPropertyType.Int:
                        if (serializedData.intParamValues.TryGetValue(propertyName, out var intValue))
                        {
                            if (intValue != material.GetInt(propertyName)) return false;   
                        }
                        else
                        {
                            return false;
                        }
                        break;
                    case ShaderPropertyType.Float:
                        if (serializedData.floatParamValues.TryGetValue(propertyName, out var floatValue))
                        {
                            if (!floatValue.Equals(material.GetFloat(propertyName))) return false;   
                        }
                        else
                        {
                            return false;
                        }
                        break;
                    case ShaderPropertyType.Range:
                        if (serializedData.rangeParamValues.TryGetValue(propertyName, out var rangeValue))
                        {
                            if (!rangeValue.Equals(new SerializedRange()
                                {
                                    value = material.GetFloat(propertyName),
                                    range = material.shader.GetPropertyRangeLimits(i)
                                }))
                            {
                                return false;
                            }
                        }
                        else
                        {
                            return false;
                        }
                        break;
                    case ShaderPropertyType.Vector:
                        if (serializedData.vectorParamValues.TryGetValue(propertyName, out var vectorValue))
                        {
                            if (!vectorValue.Equals(material.GetVector(propertyName))) return false;   
                        }
                        else
                        {
                            return false;
                        }
                        break;
                    case ShaderPropertyType.Color:
                        if (serializedData.colorParamValues.TryGetValue(propertyName, out var colorValue))
                        {
                            if (!colorValue.Equals(material.GetColor(propertyName))) return false;   
                        }
                        else
                        {
                            return false;
                        }
                        break;
                    case ShaderPropertyType.Texture:
                        if (serializedData.textureParamValues.TryGetValue(propertyName, out var textureValue))
                        {
                            var materialTexture = material.GetTexture(propertyName);
                            var materialTexturePath = AssetDatabase.GetAssetPath(materialTexture);
                            var materialTextureGuid = AssetDatabase.AssetPathToGUID(materialTexturePath);
                            var isTexEqual = textureValue.Equals(new SerializedTexture()
                            {
                                guid = materialTextureGuid,
                                tilling = material.GetTextureScale(propertyName),
                                offset = material.GetTextureOffset(propertyName),
                            });
                            if (!isTexEqual) return false;
                        }
                        else
                        {
                            return false;
                        }
                        break;
                }
            }
            return true;
        }

        public bool ApplyToMaterial(Material material, HashSet<string> lockedPropertyNames)
        {
            if (material.shader.name != serializedData.shaderName) return false;
            ApplyToMaterialWithoutTex(material, lockedPropertyNames);
            foreach (var kv in serializedData.textureParamValues)
            {
                var paramName = kv.Key;
                if (lockedPropertyNames != null && lockedPropertyNames.Contains(paramName)) continue;
                var serializedTexture = kv.Value;
                var path = AssetDatabase.GUIDToAssetPath(serializedTexture.guid);
                var texture = AssetDatabase.LoadAssetAtPath<Texture>(path);
                if (texture)
                {
                    material.SetTexture(paramName, texture);
                }
                material.SetTextureOffset(paramName, serializedTexture.offset);
                material.SetTextureScale(paramName, serializedTexture.tilling);
            }
            if (serializedData.shaderKeywords != null)
            {
                material.shaderKeywords = serializedData.shaderKeywords.Keys.ToArray();
                foreach (var kv in serializedData.shaderKeywords)
                {
                    var keywordName = kv.Key;
                    var value = kv.Value;
                    if (value)
                    {
                        material.EnableKeyword(keywordName);
                    }
                    else
                    {
                        material.DisableKeyword(keywordName);
                    }
                }
            }
            return true;
        }

        public List<(string, Texture)> LoadTextures()
        {
            var propertyNameTextures = new List<(string, Texture)>();
            foreach (var kv in serializedData.textureParamValues)
            {
                var propertyName = kv.Key;
                var serializedTexture = kv.Value;
                var path = AssetDatabase.GUIDToAssetPath(serializedTexture.guid);
                var texture = AssetDatabase.LoadAssetAtPath<Texture>(path);
                if (texture)
                {
                    propertyNameTextures.Add((propertyName, texture));   
                }
            }
            return propertyNameTextures;
        }
#endif
    }
