// ----------  organic path ------------------------------------------------
const makeBlobPath = (R: number, t: number, clarity: CognitionLevel) => {
  'worklet';
  const pts = 48;
  const ampl = Math.min(0.08, Math.max(0.05, 0.18 - clarity * 0.02));
  const p: [number, number][] = [];
  for (let i = 0; i < pts; ++i) {
    const a = (i / pts) * Math.PI * 2;
    const n = Math.sin(a * 3 + t * 2) * 0.6 + Math.sin(a * 7 + t) * 0.4;
    const r = R * (1 + ampl * n);
    p.push([Math.cos(a) * r, Math.sin(a) * r]);
  }
  const path = Skia.Path.Make();
  for (let i = 0; i < pts; ++i) {
    const p0 = p[(i - 1 + pts) % pts], p1 = p[i], p2 = p[(i + 1) % pts], p3 = p[(i + 2) % pts];
    if (i === 0) path.moveTo(...p1);
    path.cubicTo(
      p1[0] + (p2[0] - p0[0]) / 6, p1[1] + (p2[1] - p0[1]) / 6,
      p2[0] - (p3[0] - p1[0]) / 6, p2[1] - (p3[1] - p1[1]) / 6,
      ...p2
    );
  }
  path.close();
  return path;
};

