                                    <Input
                                        type="text"
                                        value={searchFilter}
                                        onChange={(e) => setSearchFilter(e.target.value)}
                                        placeholder="Search Event Logs"
                                    />
                                </Col>
                            </Row>
                            {/* Wrapper for ReactTable to handle its own scrolling */}
                            <div
                                style={{
                                    flex: 1, // This div will take the remaining height
                                    overflowY: 'auto', // Add scrollbar if table content overflows
                                    // Make sure this div provides a definite height for ReactTable
