    def levelOrder(self, root: Optional[TreeNode]) -> List[List[int]]:
        level_order = []
        cur_level = []
        if root is None:
            return level_order
        q = [root, None]
        index = 0
        while index <= len(q) - 1:
            if q[index] is not None:
                cur_level.append(q[index].val)
                if q[index].left is not None:
                    q.append(q[index].left)
                if q[index].right is not None:
                    q.append(q[index].right)

            else:
                level_order.append(cur_level)
                cur_level = []
                if index < len(q) - 1:
