Sure! Below is a complete single-file index.html that creates an in-browser JavaScript code editor using the CodeMirror 6 library via CDN. It includes:

- Syntax highlighting for JavaScript.
- Line numbers.
- Editable code area.
- Optional Tailwind CSS for styling (but works without it).
- All logic and layout in one self-contained HTML file.

📄 index.html:

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>In-Browser Code Editor</title>

  <!-- Optional Tailwind CSS CDN -->
  <script src="https://cdn.tailwindcss.com"></script>

  <!-- CodeMirror 6 CDN dependencies -->
  <script type="module">
    import {EditorView, basicSetup} from "https://esm.sh/@codemirror/basic-setup@0.20.2";
    import {EditorState} from "https://esm.sh/@codemirror/state@0.19.1";
    import {javascript} from "https://esm.sh/@codemirror/lang-javascript@0.19.5";
    import {oneDark} from "https://esm.sh/@codemirror/theme-one-dark@0.19.5";

    window.initEditor = () => {
      const startCode = `// Welcome to the in-browser code editor!
function greet(name) {
  console.log("Hello, " + name + "!");
}

greet("World");`;

      const state = EditorState.create({
        doc: startCode,
        extensions: [
          basicSetup,
          javascript(),
          oneDark
        ]
      });

      const view = new EditorView({
        state,
        parent: document.getElementById("editor")
      });
    };
  </script>

  <style>
    body {
      margin: 0;
