проведи код ревью этого метода
public function importOrders(): array
    {
        $newOrders = $this->getNewOrders();
        if (empty($newOrders)) {
            throw new \Exception('Нет заказов для импорта.');
        }

        $prepareNewOrders = $this->prepareNewOrders($newOrders);
        $orderUuids = array_keys($prepareNewOrders);

        $currentOrders = GlobalTransferOrder::query()
            ->with((['positions' => function ($query) {
                $query->get()->keyBy('warehouse_item_uuid');
            }]))
            ->whereIn('uuid', $orderUuids)
            ->get()
            ->keyBy('uuid')
            ->toArray();

        DB::connection('ware_mysql')->beginTransaction();
        try {
            $newOrderPositions = [];
            foreach ($prepareNewOrders as $uuid => $order) {
                if (array_key_exists($uuid, $currentOrders)) {
                    if ($currentOrders[$uuid]['updated_status_at'] > $order['last_modified']) {
                        unset($order['status']);
                    }
                    GlobalTransferOrder::where('uuid', $uuid)->update($order);
                    foreach ($order['positions'] as $keyPosition => $position) {
                        if (!empty($currentOrders[$uuid]['positions'][$keyPosition])) {
                            $newOrderPositions[] = $position;
                        } else if ($position['quantity'] != $currentOrders[$uuid]['position'][$keyPosition]['quantity']) {
                            GlobalTransferOrderPosition::query()
                                ->where('global_transfer_order_uuid', $order['uuid'])
                                ->where('warehouse_item_uuid', array_keys($order['positions']))
                                ->update([
                                    'quantity' => $position['quantity']
                                ]);
                        }
                    }
                    GlobalTransferOrderPosition::query()
                        ->where('global_transfer_order_uuid', $order['uuid'])
                        ->whereNotIn('warehouse_item_uuid', array_keys($order['positions']))
                        ->delete();
                } else {
                    $newOrders[] = $order;
                    $newOrderPositions = array_merge($newOrderPositions, $order['positions']);
                }
            }
            GlobalTransferOrder::insertOrIgnore($newOrders);
            GlobalTransferOrderPosition::insertOrIgnore($newOrderPositions);

            DB::connection('ware_mysql')->commit();

            return ['success' => true, 'imported_count' => count($prepareNewOrders['orders'])];
        } catch (\Throwable $e) {
            DB::connection('ware_mysql')->rollBack();
            throw new \Exception('Ошибка при импорте заказов на перемещение!');
        }
    }

