  font-size: 1.2em;
  margin-top: 10px;
}

#restart {
  margin-top: 15px;
  padding: 10px 20px;
  background: #333;
  color: #fff;
  border: none;
  cursor: pointer;
  font-size: 1em;
  transition: background 0.3s ease;
}

#restart:hover {
  background: #444;
