```

---

### 🔹 `script.js`

```javascript
const board = document.getElementById('board');
const statusDiv = document.getElementById('status');
const timeSpan = document.getElementById('time');
const restartButton = document.getElementById('restart');

let currentPlayer = 'X';
let cells = Array(9).fill('');
let isGameOver = false;
let timer = 10;
let timerInterval;

function createBoard() {
  board.innerHTML = '';
  for (let i = 0; i < 9; i++) {
    const cell = document.createElement('div');
    cell.classList.add('cell');
    cell.dataset.index = i;
    cell.addEventListener('click', handleMove);
    board.appendChild(cell);
  }
}

function startTimer() {
  timer = 10;
  timeSpan.textContent = timer;
  clearInterval(timerInterval);
  timerInterval = setInterval(() => {
    timer--;
    timeSpan.textContent = timer;
    if (timer <= 0) {
      clearInterval(timerInterval);
      switchPlayer(); // Auto-switch turn on timeout
    }
  }, 1000);
}

function handleMove(e) {
  const index = e.target.dataset.index;
  if (cells[index] !== '' || isGameOver) return;

  cells[index] = currentPlayer;
  e.target.textContent = currentPlayer;

  if (checkWin(currentPlayer)) {
    statusDiv.textContent = `Player ${currentPlayer} wins!`;
    isGameOver = true;
    clearInterval(timerInterval);
  } else if (cells.every(cell => cell !== '')) {
    statusDiv.textContent = `It's a draw!`;
    isGameOver = true;
    clearInterval(timerInterval);
  } else {
    switchPlayer();
  }
}

function switchPlayer() {
  currentPlayer = currentPlayer === 'X' ? 'O' : 'X';
  statusDiv.textContent = `Player ${currentPlayer}'s turn`;
  startTimer();
}

function checkWin(player) {
  const winCombinations = [
    [0,1,2], [3,4,5], [6,7,8], // Rows
    [0,3,6], [1,4,7], [2,5,8], // Columns
    [0,4,8], [2,4,6]           // Diagonals
  ];
  return winCombinations.some(combo => 
    combo.every(index => cells[index] === player)
  );
}

function restartGame() {
  cells = Array(9).fill('');
  currentPlayer = 'X';
  isGameOver = false;
  statusDiv.textContent = `Player ${currentPlayer}'s turn`;
  createBoard();
  startTimer();
}

// Attach restart event
restartButton.addEventListener('click', restartGame);

// Initialize game
createBoard();
restartGame();
```

---

## 🚀 How to Use

1. Save the 3 code files in the same directory:
   - `index.html`
   - `style.css`
   - `script.js`
2. Open `index.html` in a browser to play!

---

## ✅ Notes

- You can change the timer limit by editing the `timer = 10;` line in `startTimer()` function.
- For advanced users, consider adding sound effects, local storage for scores, or multiplayer over WebSocket.

